import unittest

from ledger import balance

A = "alice"
B = "bob"


def ev(id_, seq, account, kind, cents=None, target=None):
    e = {"id": id_, "seq": seq, "account": account, "kind": kind}
    if cents is not None:
        e["cents"] = cents
    if target is not None:
        e["target"] = target
    return e


class TestNormalBehavior(unittest.TestCase):
    def test_empty_input_returns_zero(self):
        self.assertEqual(balance([], A), 0)

    def test_input_is_unordered_processed_by_ascending_seq(self):
        events = [
            ev("d", 4, A, "debit", 5),
            ev("c", 1, A, "credit", 100),
            ev("c2", 7, A, "credit", 25),
        ]
        self.assertEqual(balance(events, A), 120)

    def test_credit_debit_sum_for_requested_account(self):
        events = [
            ev("c1", 1, A, "credit", 100),
            ev("c2", 2, A, "credit", 250),
            ev("d1", 3, A, "debit", 75),
        ]
        self.assertEqual(balance(events, A), 275)

    def test_other_accounts_share_the_ledger_but_not_the_balance(self):
        events = [
            ev("c1", 1, A, "credit", 100),
            ev("c2", 2, B, "credit", 9999),
            ev("d1", 3, A, "debit", 25),
        ]
        self.assertEqual(balance(events, A), 75)
        self.assertEqual(balance(events, B), 9999)

    def test_exact_duplicate_delivery_retries_count_once(self):
        dup = ev("c1", 1, A, "credit", 100)
        events = [dup, dict(dup), ev("d1", 3, A, "debit", 20)]
        self.assertEqual(balance(events, A), 80)

    def test_exact_duplicate_of_reversal_counts_once(self):
        events = [
            ev("c1", 1, A, "credit", 100),
            ev("r1", 2, A, "reverse", target="c1"),
            ev("r1", 2, A, "reverse", target="c1"),
        ]
        self.assertEqual(balance(events, A), 0)

    def test_reversal_cancels_target_signed_amount(self):
        events = [
            ev("c1", 1, A, "credit", 100),
            ev("d1", 2, A, "debit", 40),
            ev("r1", 3, A, "reverse", target="c1"),
            ev("r2", 4, A, "reverse", target="d1"),
        ]
        self.assertEqual(balance(events, A), 0)

    def test_reversal_in_other_account_does_not_touch_balance(self):
        events = [
            ev("c1", 1, A, "credit", 100),
            ev("c2", 2, B, "credit", 50),
            ev("r1", 3, B, "reverse", target="c2"),
        ]
        self.assertEqual(balance(events, A), 100)

    def test_input_is_not_mutated(self):
        events = [
            ev("c1", 2, A, "credit", 100),
            ev("d1", 1, A, "debit", 3),
        ]
        snapshot = [dict(e) for e in events]
        balance(events, A)
        self.assertEqual(events, snapshot)

    def test_return_value_is_plain_integer(self):
        self.assertIsInstance(balance([ev("c1", 1, A, "credit", 10)], A), int)


class TestValidation(unittest.TestCase):
    def test_reverse_does_not_read_cents(self):
        # Old code did total -= e['cents'] on reversals, which has no cents key.
        events = [
            ev("c1", 1, A, "credit", 100),
            ev("r1", 2, A, "reverse", target="c1"),
        ]
        self.assertEqual(balance(events, A), 0)

    def test_reused_id_with_different_content_raises(self):
        events = [
            ev("x", 1, A, "credit", 10),
            ev("x", 2, A, "credit", 20),
        ]
        with self.assertRaises(ValueError):
            balance(events, A)

    def test_reused_id_with_different_content_on_another_account_raises(self):
        events = [
            ev("x", 1, A, "credit", 10),
            ev("x", 2, B, "credit", 10),
        ]
        with self.assertRaises(ValueError):
            balance(events, A)

    def test_unknown_kind_raises(self):
        with self.assertRaises(ValueError):
            balance([ev("x", 1, A, "bonus", 5)], A)

    def test_unknown_kind_in_other_account_raises(self):
        with self.assertRaises(ValueError):
            balance([ev("x", 1, B, "bonus", 5)], A)

    def test_negative_cents_raises(self):
        for cents in (-1, -100):
            with self.assertRaises(ValueError):
                balance([ev("x", 1, A, "credit", cents)], A)

    def test_float_cents_raises(self):
        with self.assertRaises(ValueError):
            balance([ev("x", 1, A, "credit", 1.5)], A)

    def test_bool_cents_raises(self):
        with self.assertRaises(ValueError):
            balance([ev("x", 1, A, "credit", True)], A)

    def test_decimal_string_cents_raises(self):
        with self.assertRaises(ValueError):
            balance([ev("x", 1, A, "credit", "12")], A)

    def test_duplicate_seq_across_distinct_events_raises(self):
        events = [
            ev("a", 1, A, "credit", 10),
            ev("b", 1, A, "credit", 20),
        ]
        with self.assertRaises(ValueError):
            balance(events, A)

    def test_duplicate_seq_reversal_target_pair_raises(self):
        events = [
            ev("c1", 1, A, "credit", 10),
            ev("r1", 1, A, "reverse", target="c1"),
        ]
        with self.assertRaises(ValueError):
            balance(events, A)

    def test_reversal_target_missing_raises(self):
        with self.assertRaises(ValueError):
            balance([ev("r1", 1, A, "reverse", target="ghost")], A)

    def test_reversal_target_later_raises(self):
        events = [
            ev("r1", 1, A, "reverse", target="c1"),
            ev("c1", 2, A, "credit", 10),
        ]
        with self.assertRaises(ValueError):
            balance(events, A)

    def test_reversal_target_another_reversal_raises(self):
        events = [
            ev("c1", 1, A, "credit", 10),
            ev("r1", 2, A, "reverse", target="c1"),
            ev("r2", 3, A, "reverse", target="r1"),
        ]
        with self.assertRaises(ValueError):
            balance(events, A)

    def test_reversal_target_in_another_account_raises(self):
        events = [
            ev("c1", 1, A, "credit", 10),
            ev("r1", 2, B, "reverse", target="c1"),
        ]
        with self.assertRaises(ValueError):
            balance(events, A)

    def test_already_reversed_target_raises(self):
        events = [
            ev("c1", 1, A, "credit", 10),
            ev("r1", 2, A, "reverse", target="c1"),
            ev("r2", 3, A, "reverse", target="c1"),
        ]
        with self.assertRaises(ValueError):
            balance(events, A)

    def test_duplicate_id_retry_that_would_alias_a_reversal_is_safe(self):
        # Delivery retry of the reversal must not count as a second reversal.
        base = [
            ev("c1", 1, A, "credit", 10),
            ev("r1", 2, A, "reverse", target="c1"),
            ev("c2", 3, A, "credit", 10),
        ]
        retry = base + [dict(base[1])]
        self.assertEqual(balance(base, A), 10)
        self.assertEqual(balance(retry, A), 10)


if __name__ == "__main__":
    unittest.main()

